// Generated by `denext mobile add-ota` (denext over-the-air UI updates). Safe to commit;
// re-run `denext mobile add-ota` after upgrading denext (then ship a new binary). See
// https://denext.dev/docs/desktop.

@preconcurrency import Capacitor
import ObjectiveC
import UIKit
import WebKit

/// A `CAPBridgeViewController` that serves the over-the-air UI (see `DenextOtaStore`). Its
/// router (`DenextOtaRouter`) serves a downloaded UI's files only while they match the UI's
/// signed manifest, and `DenextOtaFileGuard` applies the same check to the
/// `/_capacitor_file_` requests Capacitor answers without the router.
///
/// Use it where the app would use `CAPBridgeViewController`: `Main.storyboard`'s view
/// controller class and `SceneDelegate`'s root view controller (`denext mobile add-ota`
/// sets both when they still name `CAPBridgeViewController`). An app with its own bridge
/// subclass changes that subclass's superclass to `DenextBridgeViewController` and calls
/// `super` from any `instanceDescriptor()` / `capacitorDidLoad()` override.
///
/// `CAPBridgeViewController.loadView()` calls `instanceDescriptor()` first, before the bridge
/// exists, then creates the bridge (which injects Capacitor's JS as document-start scripts)
/// and calls `capacitorDidLoad()`; the page itself loads later, from `viewDidLoad()`. So the
/// start directory is chosen, and the `DenextOta` plugin registered, before the first page.
///
/// A web content process that terminates is reloaded by Capacitor's own navigation delegate
/// (`loadView()` is final, so this class cannot replace it). If that reload leaves a trial UI
/// blank, the watchdog rolls it back.
class DenextBridgeViewController: CAPBridgeViewController {
    /// Serves an exported multi-page app's routes: Capacitor's router answers every path
    /// without an extension with the root `index.html` (a single-page-app assumption), so
    /// `/protected` would load the home page.
    override open func router() -> Router {
        DenextOtaRouter()
    }

    /// Whether this launch serves a downloaded UI on its trial launch.
    private var otaTrialLaunch = false

    /// Picks which UI directory the app starts from (a confirmed or trial over-the-air UI,
    /// else the bundled `public/`), rolling back a trial the app died in before the page loads.
    override func instanceDescriptor() -> InstanceDescriptor {
        let descriptor = super.instanceDescriptor()
        let launch = DenextOtaStore.shared.prepareLaunch()
        if let directory = launch.directory {
            descriptor.appLocation = directory
        }
        otaTrialLaunch = launch.trial
        return descriptor
    }

    override func capacitorDidLoad() {
        super.capacitorDidLoad()
        // denext: native plugin calls are accepted from the app's main frame only.
        DenextMainFrameBridgeGuard.install(on: bridge)
        // denext: the OS's low-memory warning reaches the page (AppState's memoryWarning).
        DenextMemoryWarning.install(on: bridge)
        let failure = DenextOtaFileGuard.install(on: bridge)
        let optedOut = bridge?.config.getPluginConfig("DenextBridge").getBoolean("otaFileGuard", true) == false
        if DenextOtaStore.shared.settleFileGuard(failure: failure, optedOut: optedOut) {
            // No file guard: the downloaded UI the launch chose is not served. The page has not
            // loaded yet (viewDidLoad loads it), so pointing the bridge at the bundled UI is enough.
            otaTrialLaunch = false
            if let bundled = DenextOtaStore.bundledDirectory {
                bridge?.setServerBasePath(bundled.path)
            }
        }
        let plugin = DenextOtaPlugin()
        bridge?.registerPluginInstance(plugin)
        // denext auth sessions: openAuthSession() in denext/mobile.
        bridge?.registerPluginInstance(DenextAuthSessionPlugin())
        // denext share extension: onShareReceived() in denext/mobile.
        bridge?.registerPluginInstance(DenextShareReceivePlugin())
        // denext widgets: setWidgetData() / reloadWidgets() in denext/mobile.
        bridge?.registerPluginInstance(DenextWidgetsPlugin())
        // denext Live Activities: startLiveActivity() in denext/mobile.
        bridge?.registerPluginInstance(DenextLiveActivityPlugin())
        // denext app settings: openAppSettings() in denext/mobile.
        bridge?.registerPluginInstance(DenextSettingsPlugin())
        // denext native menus: showContextMenu() / useContextMenu() in denext/mobile.
        bridge?.registerPluginInstance(DenextContextMenuPlugin())
        // denext SF Symbols: <SystemIcon> in denext/mobile.
        bridge?.registerPluginInstance(DenextSystemIconPlugin())
        if otaTrialLaunch {
            plugin.armWatchdog()
        }
    }
}

/// Capacitor's asset handler reads a `/_capacitor_file_<path>` request straight from `<path>`
/// (`Capacitor.convertFileSrc`) without asking the router, and `loadView()`, which creates the
/// handler, is final. So the handler the bridge made becomes this subclass (it adds no stored
/// properties), which asks `DenextOtaStore.admitCapacitorFile` first: a file inside the
/// versions root is served only when it matches its UI's signed manifest. Every other request,
/// and every file outside the versions root, goes to Capacitor's handler unchanged.
final class DenextOtaFileGuard: WebViewAssetHandler {
    override func webView(_ webView: WKWebView, start urlSchemeTask: WKURLSchemeTask) {
        // WKURLSchemeHandler calls arrive on the main thread.
        if let path = urlSchemeTask.request.url?.path, !DenextOtaStore.shared.admitCapacitorFile(path) {
            urlSchemeTask.didFailWithError(URLError(.fileDoesNotExist))
            return
        }
        super.webView(webView, start: urlSchemeTask)
    }

    /// Main thread, from `capacitorDidLoad()` (before the first page). Returns nil once the guard
    /// is in place, else why it is not: no bridge or web view, no handler for the app's scheme, or
    /// a handler of the app's own class (only Capacitor's own class is changed). The caller hands
    /// that to `DenextOtaStore.settleFileGuard`, which then serves no downloaded UI.
    static func install(on bridge: CAPBridgeProtocol?) -> String? {
        guard let bridge = bridge, let scheme = bridge.config.localURL.scheme,
              let handler = bridge.webView?.configuration.urlSchemeHandler(forURLScheme: scheme) else {
            return "the web view has no asset handler to guard /_capacitor_file_ requests"
        }
        if handler is DenextOtaFileGuard { return nil }
        guard object_getClass(handler) == WebViewAssetHandler.self else {
            return "the web view's asset handler is the app's own class, so /_capacitor_file_ requests cannot be guarded"
        }
        object_setClass(handler, DenextOtaFileGuard.self)
        return nil
    }
}

/// Forwards the OS's low-memory warning to the page as the "denext:memorywarning" window
/// event, which React Native mode's AppState emits as "memoryWarning".
@MainActor
enum DenextMemoryWarning {
    /// The notification observer (one per process: a recreated bridge replaces it).
    private static var observer: NSObjectProtocol?

    /// Observes UIApplication.didReceiveMemoryWarningNotification for the bridge's page. Call
    /// it from capacitorDidLoad().
    static func install(on bridge: CAPBridgeProtocol?) {
        if let observer { NotificationCenter.default.removeObserver(observer) }
        observer = NotificationCenter.default.addObserver(
            forName: UIApplication.didReceiveMemoryWarningNotification,
            object: nil,
            queue: .main
        ) { [weak bridge] _ in
            MainActor.assumeIsolated {
                bridge?.triggerWindowJSEvent(eventName: "denext:memorywarning")
            }
        }
    }
}

/// Drops native bridge calls that do not come from the app's own main frame.
///
/// WebKit delivers the bridge script message from every frame of the page, and Capacitor's
/// handler does not check which frame sent it, so an iframe (an embedded site, an ad, a widget)
/// could call any installed plugin. Capacitor injects its JS bridge into the main frame only,
/// so a message from another frame is never the app's own. A main frame on another origin (a
/// server.allowNavigation site, a hosted server.url) is refused too, unless the Capacitor
/// config lists it in plugins.DenextBridge.allowedOrigins or turns the origin check off with
/// plugins.DenextBridge.frameGuard: false. This handler takes Capacitor's place under the same
/// name and forwards the accepted messages to it unchanged.
@MainActor
final class DenextMainFrameBridgeGuard: NSObject, WKScriptMessageHandler {
    /// The name Capacitor registers its handler under (WebViewDelegationHandler.handlerName).
    private static let handlerName = "bridge"
    /// The Capacitor config section the guard reads (plugins.DenextBridge).
    private static let configId = "DenextBridge"
    /// Capacitor's own handler, which the bridge owns.
    private weak var target: WKScriptMessageHandler?
    /// The origins whose main frame may call plugins; nil when the origin check is off.
    private let allowedOrigins: Set<String>?
    /// The frame origins already logged, so a looping frame cannot flood the log.
    private var logged = Set<String>()

    private init(target: WKScriptMessageHandler, allowedOrigins: Set<String>?) {
        self.target = target
        self.allowedOrigins = allowedOrigins
    }

    /// Puts the guard in front of Capacitor's bridge handler. Call it from capacitorDidLoad(),
    /// which runs before the first page loads.
    static func install(on bridge: CAPBridgeProtocol?) {
        guard let bridge = bridge as? CapacitorBridge else {
            NSLog("[denext] could not guard the native bridge: the bridge is not a CapacitorBridge")
            return
        }
        let handler = bridge.webViewDelegationHandler
        let controller = handler.contentController
        controller.removeScriptMessageHandler(forName: handlerName)
        let guardHandler = DenextMainFrameBridgeGuard(
            target: handler,
            allowedOrigins: allowedOrigins(bridge.config)
        )
        controller.add(guardHandler, name: handlerName)
    }

    /// The origins plugin calls are accepted from: the app's own (Capacitor's local URL; in a
    /// debug build also server.url, for live reload), plus plugins.DenextBridge.allowedOrigins.
    /// Nil with plugins.DenextBridge.frameGuard: false (only the main-frame check is kept).
    static func allowedOrigins(_ config: InstanceConfiguration) -> Set<String>? {
        let pluginConfig = config.getPluginConfig(configId)
        guard pluginConfig.getBoolean("frameGuard", true) else { return nil }
        var origins = Set<String>()
        if let local = origin(of: config.localURL) { origins.insert(local) }
        #if DEBUG
        if let server = origin(of: config.serverURL) { origins.insert(server) }
        #endif
        for case let entry as String in pluginConfig.getArray("allowedOrigins", []) ?? [] {
            if let url = URL(string: entry), let allowed = origin(of: url) { origins.insert(allowed) }
        }
        return origins
    }

    /// url's origin as scheme://host[:port] (lower-cased, no default port), or nil.
    static func origin(of url: URL) -> String? {
        guard let scheme = url.scheme?.lowercased(), let host = url.host?.lowercased(), !host.isEmpty else {
            return nil
        }
        return format(scheme: scheme, host: host, port: url.port ?? 0)
    }

    /// An origin as scheme://host[:port]; port 0 (WebKit's "default") and 80 / 443 for
    /// http / https are left out.
    static func format(scheme: String, host: String, port: Int) -> String {
        let isDefault = port == 0 || (scheme == "https" && port == 443) || (scheme == "http" && port == 80)
        return isDefault ? "\(scheme)://\(host)" : "\(scheme)://\(host):\(port)"
    }

    func userContentController(
        _ userContentController: WKUserContentController,
        didReceive message: WKScriptMessage
    ) {
        let origin = message.frameInfo.securityOrigin
        let from = Self.format(scheme: origin.protocol.lowercased(), host: origin.host.lowercased(), port: origin.port)
        guard message.frameInfo.isMainFrame else {
            refuse("[denext] refused a native plugin call from a non-main frame (%@)", from)
            return
        }
        if let allowed = allowedOrigins, !allowed.contains(from) {
            refuse(
                "[denext] refused a native plugin call from %@, which is not the app's origin (list it in plugins.DenextBridge.allowedOrigins)",
                from
            )
            return
        }
        target?.userContentController(userContentController, didReceive: message)
    }

    /// Logs a refusal once per origin (at most 16).
    private func refuse(_ format: String, _ from: String) {
        if logged.count < 16, logged.insert(from).inserted {
            NSLog(format, from)
        }
    }
}

/// `/route` → `/route/index.html` or `/route.html` when the export has that page, else the root
/// `index.html` (a single-page app's client routes keep working). `basePath` is the directory
/// the UI is served from (the bundled `public/` or an over-the-air UI), set by Capacitor.
/// `path` arrives decoded (`/%2e%2e%2fsecret` is `/../secret`), so a path that leaves that
/// directory is refused: a navigation gets the root `index.html`, anything else the directory
/// itself, which the asset handler cannot read (the request fails).
struct DenextExportRouter: Router {
    var basePath: String = ""
    func route(for path: String) -> String {
        let url = URL(fileURLWithPath: path)
        guard staysInside(path) else {
            return basePath + (url.pathExtension.isEmpty ? "/index.html" : "/")
        }
        guard url.pathExtension.isEmpty else { return basePath + path }
        let trimmed = path.hasSuffix("/") ? String(path.dropLast()) : path
        if !trimmed.isEmpty {
            let fm = FileManager.default
            for candidate in [trimmed + "/index.html", trimmed + ".html"] {
                if fm.fileExists(atPath: basePath + candidate) { return basePath + candidate }
            }
        }
        return basePath + "/index.html"
    }

    /// Whether `path` names a file under `basePath`: no `..` segment, and once standardized
    /// the path is `basePath` or below it.
    private func staysInside(_ path: String) -> Bool {
        if path.split(separator: "/").contains("..") { return false }
        let root = URL(fileURLWithPath: basePath.isEmpty ? "/" : basePath).standardizedFileURL.path
        let resolved = URL(fileURLWithPath: basePath + path).standardizedFileURL.path
        return resolved == root || resolved.hasPrefix(root.hasSuffix("/") ? root : root + "/")
    }
}
